+			"SubagentActive",
+		);
+
+		requestsTaskStop("patient-review", "tu-stop-null");
+		taskStopResult("tu-stop-null", null);
+		expect((await stopEntry("tFAIL", description))?.eventType).toBe(
+			"SubagentActive",
+		);
+	});
