new = r'''def _team_empty_ledger():
    return ({}, {}, {}, {}, [], set(), 0)


def _team_ledger(transcript_path, terminal_id, entry_ids):
    # Incrementally parse the lead transcript into:
    # - name -> "active"|"idle"
    # - name -> normalized prompt/explicit-description match keys
    # - background_tasks entry id -> causally associated spawn names
    # Cache schema v6 adds explicit descriptions and trusted entry bindings.
    # Migrating v5 performs one full transcript read while preserving its live
    # bindings; a missing/corrupt cache stays conservative for description matches.
    # Never raises; every failure path returns None (keep every hold).
    if not transcript_path or not terminal_id:
        return None
    cache_file = _teamstate_path(terminal_id)
    (
        state,
        fork_tools,
        match_keys,
        entry_names,
        seen_ids,
        trusted_ids,
        offset,
    ) = _team_empty_ledger()
    incremental_binding = False
    try:
        rec = json.loads(cache_file.read_text(encoding="utf-8"))
        common = (
            isinstance(rec, dict)
            and rec.get("path") == transcript_path
            and isinstance(rec.get("state"), dict)
            and isinstance(rec.get("forkTools"), dict)
            and isinstance(rec.get("seenIds"), list)
            and isinstance(rec.get("entryNames"), dict)
        )
        if (
            common
            and rec.get("version") == 6
            and isinstance(rec.get("matchKeys"), dict)
            and all(
                isinstance(value, dict)
                for value in rec.get("matchKeys", {}).values()
            )
            and isinstance(rec.get("trustedEntryIds"), list)
        ):
            offset = int(rec.get("offset") or 0)
            state = {str(k): str(v) for k, v in rec["state"].items()}
            fork_tools = {
                str(k): str(v) for k, v in rec["forkTools"].items()
            }
            match_keys = {
                str(k): {
                    "prompt": str(v.get("prompt") or ""),
                    "description": str(v.get("description") or ""),
                }
                for k, v in rec["matchKeys"].items()
            }
            seen_ids = [str(v) for v in rec["seenIds"]]
            entry_names = {
                str(k): [str(x) for x in v]
                for k, v in rec["entryNames"].items()
                if isinstance(v, list)
            }
            trusted_ids = {str(v) for v in rec["trustedEntryIds"]}
            incremental_binding = True
        elif (
            common
            and rec.get("version") == 5
            and isinstance(rec.get("prompts"), dict)
        ):
            # Preserve v5's causal bindings while rescanning from byte zero to
            # populate explicit descriptions. Treat only those existing bindings
            # as trusted; the full-history scan cannot prove new associations.
            seen_ids = [str(v) for v in rec["seenIds"]]
            entry_names = {
                str(k): [str(x) for x in v]
                for k, v in rec["entryNames"].items()
                if isinstance(v, list)
            }
            trusted_ids = set(entry_names)
    except Exception:
        (
            state,
            fork_tools,
            match_keys,
            entry_names,
            seen_ids,
            trusted_ids,
            offset,
        ) = _team_empty_ledger()
    try:
        with open(transcript_path, "rb") as h:
            h.seek(0, 2)
            size = h.tell()
            if offset < 0 or offset > size:
                (
                    state,
                    fork_tools,
                    match_keys,
                    entry_names,
                    seen_ids,
                    trusted_ids,
                    offset,
                ) = _team_empty_ledger()
                incremental_binding = False
            h.seek(offset)
            data = h.read()
    except Exception:
        return None
    spawns = []
    nl = data.rfind(b"\n")
    if nl >= 0:
        for raw in data[:nl].split(b"\n"):
            if not raw.strip():
                continue
            try:
                obj = json.loads(raw.decode("utf-8", "replace"))
            except Exception:
                continue
            if isinstance(obj, dict):
                _team_scan_record(
                    state, fork_tools, match_keys, spawns, obj
                )
        offset = offset + nl + 1
    previously_seen = set(seen_ids)
    entry_names, seen_ids = _team_bind_entries(
        entry_names, seen_ids, entry_ids, spawns
    )
    if incremental_binding:
        for entry_id in entry_ids:
            if entry_id not in previously_seen and entry_id in entry_names:
                trusted_ids.add(entry_id)
    live_ids = set(entry_ids)
    trusted_ids = {entry_id for entry_id in trusted_ids if entry_id in live_ids}
    try:
        cache_file.parent.mkdir(parents=True, exist_ok=True)
        temp_file = cache_file.with_name(
            cache_file.name + "." + str(os.getpid()) + ".tmp"
        )
        temp_file.write_text(
            json.dumps({
                "version": 6,
                "path": transcript_path,
                "offset": offset,
                "state": state,
                "forkTools": fork_tools,
                "matchKeys": match_keys,
                "seenIds": seen_ids,
                "entryNames": entry_names,
                "trustedEntryIds": sorted(trusted_ids),
            }),
            encoding="utf-8",
        )
        os.replace(temp_file, cache_file)
    except Exception:
        pass
    return (state, match_keys, entry_names, trusted_ids)

'''
